const urgency = (inputData.urgency || "").toLowerCase().trim();
const budget = parseFloat(String(inputData.budget || "").replace(/[^0-9.]/g, ""));
const leadSource = (inputData.lead_source || "").toLowerCase().trim();

let score = 0;

// Urgency score
if (urgency === "high") {
  score += 30;
} else if (urgency === "medium") {
  score += 20;
} else if (urgency === "low") {
  score += 10;
}

// Budget score
if (budget > 5000) {
  score += 30;
} else if (budget >= 1000) {
  score += 20;
} else {
  score += 10;
}

// Lead source score
if (leadSource === "referral") {
  score += 20;
} else if (leadSource === "linkedin") {
  score += 15;
}

// Determine priority
let priority;

if (score >= 70) {
  priority = "Hot";
} else if (score >= 40) {
  priority = "Warm";
} else {
  priority = "Cold";
}

// Generate unique Lead ID
const now = new Date();
const year = now.getFullYear();
const timestamp = Date.now().toString().slice(-6);
const leadId = `LEAD-${year}-${timestamp}`;

created_at: new Date().toISOString()

return {
  lead_score: score,
  priority: priority,
  lead_id: leadId,
  created_at: new Date().toISOString()
};

